window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cea01bd3cf976bc4"]={"versions": [{"id": "FIG-cea01bd3cf976bc4", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AP), das die architektonischen Schnittstellenbeziehungen zwischen den beiden funktionalen Clustern State Management und Execution Management abbildet. Beide Entitäten sind als daemon-basierte funktionale Cluster («aapFunctionalCluster», daemon-based) ausgeführt. State Management fungiert als anfordernde Komponente (Client), während Execution Management die Implementierungsinstanz darstellt, welche die Schnittstellen bereitstellt und realisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionale Cluster:\n<ul class=\"fig-list\"><li><code>State Management</code> («aapFunctionalCluster», daemon-based): Konsument der Schnittstellen.\n</li><li><code>Execution Management</code> («aapFunctionalCluster», daemon-based): Bereitstellendes Cluster, das die Schnittstellen via UML-Interface-Realization (gestrichelte Linie mit geschlossener, nicht gefüllter Dreiecksspitze) implementiert.\n</li></ul>\n</li><li>Schnittstellen:\n<ul class=\"fig-list\"><li><code>StateClient</code> («aapAPI,aapNativeInterface»): Native C++-Schnittstelle zur Interaktion mit Execution Management.\n<ul class=\"fig-list\"><li><code>+ Create(function)</code>: Statische Fabrikmethode zur Instanziierung eines <code>StateClient</code>-Objekts mit Übergabe einer Callback- bzw. Handler-Funktion.\n</li><li><code>+ GetExecutionError()</code>: Methode zur Abfrage aufgetretener Ausführungsfehler.\n</li><li><code>+ GetInitialMachineStateTransitionResult()</code>: Methode zur Ermittlung des Übergangsergebnisses für den initialen Maschinenzustand.\n</li><li><code>+ SetState(FunctionGroupState): Future</code>: Asynchrone Methode zur Anforderung eines Zustandswechsels für eine Funktionsgruppe; liefert ein <code>Future</code>-Objekt zurück.\n</li></ul>\n</li><li><code>FunctionGroupState</code> («aapAPI,aapPortInterface»): Port-basierte Schnittstelle zur Repräsentation des Zustands einer Funktionsgruppe ohne im Diagramm definierte Operationen.\n</li></ul>\n</li><li>Schnittstellenbeziehungen:\n<ul class=\"fig-list\"><li><code>State Management</code> nutzt <code>StateClient</code> über eine generische Abhängigkeit (<code>«use»</code>).\n</li><li><code>State Management</code> referenziert <code>FunctionGroupState</code> über eine Port-Abhängigkeit (<code>«use»</code>, <code>«aapRequiredPort»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Instanziierung des <code>StateClient</code> durch State Management mittels statischer Methode <code>Create(function)</code>.\n</li><li>Abfrage des initialen Maschinenzustandsübergangs über <code>GetInitialMachineStateTransitionResult()</code>.\n</li><li>Laufende Fehlerüberwachung durch Aufruf von <code>GetExecutionError()</code>.\n</li><li>Auslösen von Funktionsgruppenzustandswechseln über <code>SetState(FunctionGroupState)</code> durch State Management.\n</li><li>Asynchrone Bearbeitung der Zustandsanforderung in Execution Management und Bereitstellung des Ergebnisses über das zurückgegebene <code>Future</code>-Objekt zur Synchronisation oder Callback-Behandlung in State Management.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>StateClient</code> erfordert eine native C++-API-Bindung («aapNativeInterface») für direkte Funktionsaufrufe.\n</li><li><code>FunctionGroupState</code> ist als Port-Interface («aapPortInterface») typisiert; State Management muss diesen Endpunkt über einen formalen Required Port («aapRequiredPort») im ARXML-Manifest konfigurieren.\n</li><li>Die Methode <code>SetState</code> erzwingt durch den Rückgabetyp <code>Future</code> ein asynchrones, nicht-blockierendes Entwurfsmuster für Zustandsübergänge zur Gewährleistung deterministischer Reaktionszeiten des Daemons.\n</li></ul>"}, {"id": "FIG-53ff797f26ea6bfa", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AP), das die architektonischen Schnittstellenbeziehungen zwischen den beiden funktionalen Clustern State Management und Execution Management abbildet. Beide Entitäten sind als daemon-basierte funktionale Cluster («aapFunctionalCluster», daemon-based) ausgeführt. State Management fungiert als anfordernde Komponente (Client), während Execution Management die Implementierungsinstanz darstellt, welche die Schnittstellen bereitstellt und realisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionale Cluster:\n<ul class=\"fig-list\"><li><code>State Management</code> («aapFunctionalCluster», daemon-based): Konsumierendes funktionales Cluster.\n</li><li><code>Execution Management</code> («aapFunctionalCluster», daemon-based): Realisierendes funktionales Cluster, das sämtliche Schnittstellen über Interface-Realization-Beziehungen implementiert.\n</li></ul>\n</li><li>Schnittstellen:\n<ul class=\"fig-list\"><li><code>StateClient</code> («aapAPI,aapNativeInterface»): Native Schnittstelle mit den Methoden:\n<ul class=\"fig-list\"><li><code>+ Create(function)</code>: Statische Fabrikmethode.\n</li><li><code>+ GetExecutionError()</code>: Abfrage von Ausführungsfehlern.\n</li><li><code>+ GetInitialMachineStateTransitionResult()</code>: Abfrage des Resultats des initialen Maschinenübergangs.\n</li><li><code>+ SetState(FunctionGroupState): Future</code>: Asynchrone Zustandsanforderung mit <code>Future</code>-Rückgabe.\n</li></ul>\n</li><li><code>FunctionGroup</code> («aapAPI,aapPortInterface»): Port-basierte Schnittstelle zur Repräsentation einer Funktionsgruppe.\n<ul class=\"fig-list\"><li><code>+ Create()</code>: Statische Fabrikmethode.\n</li></ul>\n</li><li><code>FunctionGroupState</code> («aapAPI,aapNativeInterface»): Native Schnittstelle zur Repräsentation des Zustands einer Funktionsgruppe.\n<ul class=\"fig-list\"><li><code>+ Create()</code>: Statische Fabrikmethode.\n</li></ul>\n</li></ul>\n</li><li>Schnittstellenbeziehungen:\n<ul class=\"fig-list\"><li><code>State Management</code> bindet <code>StateClient</code> via <code>«use»</code> an.\n</li><li><code>State Management</code> bindet <code>FunctionGroup</code> über einen Port via <code>«use»</code> und <code>«aapRequiredPort»</code> an.\n</li><li><code>State Management</code> bindet <code>FunctionGroupState</code> via <code>«use»</code> an.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Instanziierung des <code>StateClient</code> über <code>Create(function)</code>.\n</li><li>Erzeugung der Zielobjekte für Funktionsgruppe und Zustand über die statischen Fabrikmethoden <code>FunctionGroup.Create()</code> und <code>FunctionGroupState.Create()</code>.\n</li><li>Abfrage des initialen Maschinenzustandsübergangs über <code>GetInitialMachineStateTransitionResult()</code>.\n</li><li>Laufende Fehlerprüfung über <code>GetExecutionError()</code>.\n</li><li>Anforderung des Zustandswechsels über <code>SetState(FunctionGroupState)</code> und asynchrone Auswertung über das zurückgegebene <code>Future</code>-Objekt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>FunctionGroup</code> ist als Port-Schnittstelle («aapPortInterface») deklariert und erfordert im State Management einen expliziten Required Port («aapRequiredPort») in der Manifest-Modellierung.\n</li><li><code>FunctionGroupState</code> und <code>StateClient</code> sind native C++-Schnittstellen («aapNativeInterface»), die per In-Process-Aufruf instanziiert und verwendet werden.\n</li><li>Sowohl <code>FunctionGroup</code> als auch <code>FunctionGroupState</code> stellen statische <code>Create()</code>-Methoden zur standardisierten Objekterzeugung bereit.\n</li><li><code>SetState</code> erzwingt über das <code>Future</code>-Muster eine asynchrone Entkopplung zwischen der Zustandsanforderung durch State Management und der Prozesssteuerung in Execution Management.\n</li></ul>"}, {"id": "FIG-fd88a97d027acc7f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AP), das die architektonischen Schnittstellenbeziehungen zwischen den beiden funktionalen Clustern State Management und Execution Management abbildet. Beide Entitäten sind als daemon-basierte funktionale Cluster («aapFunctionalCluster», daemon-based) ausgeführt. State Management fungiert als anfordernde Komponente (Client), während Execution Management die Implementierungsinstanz darstellt, welche die Schnittstellen bereitstellt und realisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionale Cluster:\n<ul class=\"fig-list\"><li><code>State Management</code> («aapFunctionalCluster», daemon-based): Anforderndes funktionales Cluster.\n</li><li><code>Execution Management</code> («aapFunctionalCluster», daemon-based): Bereitstellendes Cluster, das alle Schnittstellen per Interface-Realization implementiert.\n</li></ul>\n</li><li>Schnittstellen:\n<ul class=\"fig-list\"><li><code>StateClient</code> («aapAPI,aapNativeInterface»): Native Schnittstelle zur Funktionsgruppensteuerung mit Methoden <code>+ Create(function)</code>, <code>+ GetExecutionError()</code>, <code>+ GetInitialMachineStateTransitionResult()</code> und <code>+ SetState(FunctionGroupState): Future</code>.\n</li><li><code>FunctionGroup</code> («aapAPI,aapPortInterface»): Port-basierte Schnittstelle mit statischer Fabrikmethode <code>+ Create()</code>.\n</li><li><code>FunctionGroupState</code> («aapAPI,aapNativeInterface»): Native Schnittstelle mit statischer Fabrikmethode <code>+ Create()</code>.\n</li><li><code>ExecutionClient</code> («aapAPI,aapNativeInterface»): Native Schnittstelle für Prozessausführungs- und Zustandsrückmeldungen.\n<ul class=\"fig-list\"><li><code>+ Create()</code>: Statische Fabrikmethode.\n</li><li><code>+ ReportExecutionState(ExecutionState)</code>: Methode zur Übermittlung des aktuellen Ausführungszustands an Execution Management.\n</li></ul>\n</li></ul>\n</li><li>Schnittstellenbeziehungen:\n<ul class=\"fig-list\"><li><code>State Management</code> nutzt <code>StateClient</code>, <code>FunctionGroupState</code> und <code>ExecutionClient</code> jeweils über eine generische Abhängigkeit (<code>«use»</code>).\n</li><li><code>State Management</code> bindet <code>FunctionGroup</code> als Required Port über <code>«use»</code> und <code>«aapRequiredPort»</code> an.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Erzeugung der Client-Instanzen über <code>ExecutionClient.Create()</code> und <code>StateClient.Create(function)</code>.\n</li><li>Meldung des eigenen Ausführungszustands durch State Management an Execution Management via <code>ExecutionClient.ReportExecutionState(ExecutionState)</code>.\n</li><li>Instanziierung von <code>FunctionGroup</code> und <code>FunctionGroupState</code> über deren statische Fabrikmethoden <code>Create()</code>.\n</li><li>Statusabfragen über <code>GetInitialMachineStateTransitionResult()</code> und Fehlerüberwachung über <code>GetExecutionError()</code>.\n</li><li>Anforderung von Zustandsänderungen via <code>SetState(FunctionGroupState)</code> mit asynchroner Bearbeitung und Synchronisation über den <code>Future</code>-Rückgabewert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>State Management unterliegt als adaptive Anwendung der Ausführungsüberwachung durch Execution Management und muss seinen Ausführungsstatus verbindlich über die native Schnittstelle <code>ExecutionClient</code> («aapNativeInterface») melden (<code>ReportExecutionState</code>).\n</li><li><code>FunctionGroup</code> fungiert als Port-Schnittstelle («aapPortInterface») und erfordert die Konfiguration eines entsprechenden Ports («aapRequiredPort») im Software-Komponenten-Manifest.\n</li><li><code>StateClient</code>, <code>FunctionGroupState</code> und <code>ExecutionClient</code> sind als native C++-Klassen («aapNativeInterface») spezifiziert, deren Lebenszyklus lokal über Fabrikmethoden (<code>Create</code>) gesteuert wird.\n</li><li>Die Zustandssteuerung über <code>SetState</code> bleibt durch das <code>Future</code>-Muster asynchron ausgeführt.\n</li></ul>"}], "trans": [{"from": "FIG-cea01bd3cf976bc4", "to": "FIG-53ff797f26ea6bfa", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstelle <code>FunctionGroupState</code>: Stereotyp von <code>«aapAPI,aapPortInterface»</code> zu <code>«aapAPI,aapNativeInterface»</code> geändert, statische Fabrikmethode <code>+ Create()</code> ergänzt und Port-Zuordnung <code>«aapRequiredPort»</code> entfernt (reine <code>«use»</code>-Beziehung).\n</li><li>Schnittstelle <code>FunctionGroup</code>: Hinzugefügt mit Stereotyp <code>«aapAPI,aapPortInterface»</code>, statischer Fabrikmethode <code>+ Create()</code>, Abhängigkeit von <code>State Management</code> via <code>«use»</code> und <code>«aapRequiredPort»</code> sowie Realisierungsbeziehung durch <code>Execution Management</code>.\n</li></ul>"}, {"from": "FIG-53ff797f26ea6bfa", "to": "FIG-fd88a97d027acc7f", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstelle <code>ExecutionClient</code>: Hinzugefügt mit Stereotyp <code>«aapAPI,aapNativeInterface»</code>, statischer Fabrikmethode <code>+ Create()</code> und Methode <code>+ ReportExecutionState(ExecutionState)</code>, Abhängigkeit von <code>State Management</code> via <code>«use»</code> sowie Realisierungsbeziehung durch <code>Execution Management</code>.\n</li></ul>"}]};
